#!/usr/bin/env python3
"""Merge CSV files, resolve their schema, and externally sort the result."""

import argparse
import csv
import datetime as dt
import functools
import heapq
import json
import os
import re
import sys
import tempfile
import pickle


TYPES = {"string", "int", "float", "bool", "date", "timestamp"}
TYPE_PRIORITY = ["timestamp", "date", "bool", "int", "float", "string"]
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def parse_timestamp(s):
    x = s.strip()
    if x.endswith(("Z", "z")):
        x = x[:-1] + "+00:00"
    value = dt.datetime.fromisoformat(x)
    if value.tzinfo is None:
        value = value.replace(tzinfo=dt.timezone.utc)
    return value.astimezone(dt.timezone.utc)


def parse_value(text, typ):
    if typ == "string":
        return text
    if typ == "int":
        return int(text.strip())
    if typ == "float":
        return float(text.strip())
    if typ == "bool":
        v = text.strip().lower()
        if v in {"true", "1", "yes", "y", "on"}:
            return True
        if v in {"false", "0", "no", "n", "off"}:
            return False
        raise ValueError("invalid boolean")
    if typ == "date":
        if not DATE_RE.match(text.strip()):
            raise ValueError("invalid date")
        return dt.date.fromisoformat(text.strip())
    if typ == "timestamp":
        return parse_timestamp(text)
    raise ValueError("unknown type")


def canonical(value, typ):
    if typ == "string":
        return value
    if typ == "int":
        return str(value)
    if typ == "float":
        return str(value)
    if typ == "bool":
        return "true" if value else "false"
    if typ == "date":
        return value.isoformat()
    if typ == "timestamp":
        text = value.isoformat(timespec="auto")
        return text[:-6] + "Z" if text.endswith("+00:00") else text


def value_type(s):
    """Return the narrow type represented by a non-null cell, or string."""
    for typ in TYPE_PRIORITY:
        try:
            parse_value(s, typ)
            return typ
        except (ValueError, OverflowError):
            pass
    return "string"


def csv_reader(path, args):
    f = open(path, "r", encoding="utf-8", newline="")
    return f, csv.reader(f, delimiter=",", quotechar=args.csv_quotechar,
                           escapechar=args.csv_escapechar)


def compare_values(a, b, desc):
    if a is None and b is None:
        return 0
    if a is None:
        return -1
    if b is None:
        return 1
    try:
        c = (a > b) - (a < b)
    except TypeError:
        c = (repr(a) > repr(b)) - (repr(a) < repr(b))
    return -c if desc else c


def make_comparator(desc):
    def cmp(left, right):
        # records are (key tuple, sequence number, output row)
        for a, b in zip(left[0], right[0]):
            c = compare_values(a, b, desc)
            if c:
                return c
        return (left[1] > right[1]) - (left[1] < right[1])
    return cmp


class HeapItem:
    def __init__(self, record, iterator, cmp):
        self.record, self.iterator, self.cmp = record, iterator, cmp

    def __lt__(self, other):
        return self.cmp(self.record, other.record) < 0


def read_schema(path):
    with open(path, encoding="utf-8") as f:
        obj = json.load(f)
    columns = obj.get("columns")
    if not isinstance(columns, list) or not columns:
        raise ValueError("schema must contain a non-empty columns list")
    result = []
    names = set()
    for col in columns:
        if not isinstance(col, dict) or not isinstance(col.get("name"), str):
            raise ValueError("each schema column needs a name and type")
        name, typ = col["name"], col.get("type")
        if not isinstance(typ, str) or typ not in TYPES or name in names:
            raise ValueError("invalid or duplicate schema column")
        names.add(name)
        result.append((name, typ))
    return result


def infer_schema(inputs, args):
    names = set()
    observed = {}
    for path in inputs:
        f, reader = csv_reader(path, args)
        try:
            header = next(reader)
            if len(header) != len(set(header)):
                raise ValueError(f"duplicate column in header of {path}")
            names.update(header)
            for name in header:
                observed.setdefault(name, set())
            for row in reader:
                for name, cell in zip(header, row):
                    if cell == "" or cell == args.csv_null_literal:
                        continue
                    observed[name].add(value_type(cell))
        finally:
            f.close()
    schema = []
    for name in sorted(names):
        types = observed.get(name, set())
        if not types:
            typ = "string"
        elif args.infer == "strict":
            typ = next(iter(types)) if len(types) == 1 else "string"
        else:
            # A type is selected only when every observed value parses as it.
            # The ordered list also gives temporal values precedence.
            typ = "string"
            # value_type's result is sufficient for strict; loose's useful
            # distinction is that int and float remain numeric together.
            if types <= {"int"}:
                typ = "int"
            elif types <= {"int", "float"}:
                typ = "float"
            elif len(types) == 1:
                typ = next(iter(types))
        schema.append((name, typ))
    return schema


def run_reader(path, args, schema, indexes, sequence_start):
    f, reader = csv_reader(path, args)
    try:
        header = next(reader)
        positions = {name: i for i, name in enumerate(header)}
        for row in reader:
            output, typed = [], []
            for name, typ in schema:
                pos = positions.get(name)
                text = row[pos] if pos is not None and pos < len(row) else None
                if text is None or text == "" or text == args.csv_null_literal:
                    output.append(args.csv_null_literal)
                    typed.append(None)
                else:
                    try:
                        val = parse_value(text, typ)
                        output.append(canonical(val, typ))
                        typed.append(val)
                    except (ValueError, OverflowError) as exc:
                        if args.on_type_error == "fail":
                            raise ValueError(f"{path}: column {name}: {exc}: {text!r}")
                        if args.on_type_error == "keep-string":
                            output.append(text)
                            typed.append(text)
                        else:
                            output.append(args.csv_null_literal)
                            typed.append(None)
            yield (tuple(typed[i] for i in indexes), sequence_start, output)
            sequence_start += 1
    finally:
        f.close()


def write_run(records, directory):
    records.sort(key=functools.cmp_to_key(write_run.cmp))
    fd, path = tempfile.mkstemp(prefix="merge-", suffix=".run", dir=directory)
    with os.fdopen(fd, "wb") as f:
        for record in records:
            pickle.dump(record, f, protocol=pickle.HIGHEST_PROTOCOL)
    return path


def iter_run(path):
    with open(path, "rb") as f:
        while True:
            try:
                yield pickle.load(f)
            except EOFError:
                return


def merge_run_group(paths, directory, cmp):
    its = [iter_run(p) for p in paths]
    heap = []
    for it in its:
        try:
            rec = next(it)
            heapq.heappush(heap, HeapItem(rec, it, cmp))
        except StopIteration:
            pass
    fd, out = tempfile.mkstemp(prefix="merge-", suffix=".run", dir=directory)
    with os.fdopen(fd, "wb") as f:
        while heap:
            item = heapq.heappop(heap)
            pickle.dump(item.record, f, protocol=pickle.HIGHEST_PROTOCOL)
            try:
                item.record = next(item.iterator)
                heapq.heappush(heap, item)
            except StopIteration:
                pass
    return out


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--output", required=True)
    p.add_argument("--key", required=True)
    p.add_argument("--desc", action="store_true")
    p.add_argument("--schema")
    p.add_argument("--infer", choices=("strict", "loose"), default="strict")
    p.add_argument("--on-type-error", choices=("coerce-null", "fail", "keep-string"), default="coerce-null")
    p.add_argument("--memory-limit-mb", type=int, default=128)
    p.add_argument("--temp-dir")
    p.add_argument("--csv-quotechar", default='"')
    p.add_argument("--csv-escapechar", default=None)
    p.add_argument("--csv-null-literal", default="")
    p.add_argument("inputs", nargs="+")
    args = p.parse_args(argv)
    if args.memory_limit_mb <= 0 or len(args.csv_quotechar) != 1 or (args.csv_escapechar is not None and len(args.csv_escapechar) != 1):
        p.error("invalid memory or CSV character option")
    try:
        schema = read_schema(args.schema) if args.schema else infer_schema(args.inputs, args)
        names = [n for n, _ in schema]
        keys = args.key.split(",")
        if not keys or any(k == "" or k not in names for k in keys):
            raise ValueError("every --key column must be present in the resolved schema")
        indexes = [names.index(k) for k in keys]
        cmp = make_comparator(args.desc)
        write_run.cmp = cmp
        directory = args.temp_dir or tempfile.gettempdir()
        os.makedirs(directory, exist_ok=True)
        run_paths, records = [], []
        used = 0
        sequence = 0
        # Keep a substantial margin for Python objects and the merge heap.
        limit = max(1 << 20, args.memory_limit_mb * 1024 * 1024 // 2)
        for path in args.inputs:
            for record in run_reader(path, args, schema, indexes, sequence):
                sequence = record[1] + 1
                records.append(record)
                used += sum(len(str(x)) for x in record[2]) + 128
                if used >= limit:
                    run_paths.append(write_run(records, directory))
                    records, used = [], 0
        if records:
            run_paths.append(write_run(records, directory))
        records = []
        cmp = make_comparator(args.desc)
        # Limit open files while retaining external-sort behavior.
        while len(run_paths) > 64:
            new_paths = []
            for i in range(0, len(run_paths), 64):
                group = run_paths[i:i + 64]
                new_paths.append(merge_run_group(group, directory, cmp))
                for old in group:
                    os.unlink(old)
            run_paths = new_paths
        output = sys.stdout if args.output == "-" else open(args.output, "w", encoding="utf-8", newline="")
        try:
            writer = csv.writer(output, delimiter=",", quotechar='"', escapechar=None, lineterminator="\n")
            writer.writerow(names)
            if run_paths:
                its = [iter_run(x) for x in run_paths]
                heap = []
                for it in its:
                    try:
                        rec = next(it)
                        heapq.heappush(heap, HeapItem(rec, it, cmp))
                    except StopIteration:
                        pass
                while heap:
                    item = heapq.heappop(heap)
                    writer.writerow(item.record[2])
                    try:
                        item.record = next(item.iterator)
                        heapq.heappush(heap, item)
                    except StopIteration:
                        pass
        finally:
            if output is not sys.stdout:
                output.close()
    except Exception as exc:
        print(f"merge_files.py: {exc}", file=sys.stderr)
        return 1
    finally:
        for path in locals().get("run_paths", []):
            try:
                os.unlink(path)
            except OSError:
                pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

